// Your book of contractors. Replace with Google Sheets -> Get rows, Airtable, Postgres, a CRM.
//
// `known_status` is what you recorded last time. Leave it blank on the first run - everything
// simply reads as new information rather than as a change.
//
// These five rows are real licences, chosen so one lands in each outcome.
return [
  { json: { company: 'BENITEZ, MICHAEL', state: 'FL', license_number: 'CGC1522906',
            known_status: 'Current,Active' } },
  { json: { company: 'CONSTRUCTION SERVICES', state: 'CA', license_number: '691876',
            known_status: 'This license is current and active.' } },
  { json: { company: 'SMITH PLUMBING SERVICE', state: 'CA', license_number: '1111665',
            known_status: 'This license is current and active.' } },
  { json: { company: 'CONSTRUCTION', state: 'NV', license_number: '',
            known_status: 'Active' } },
  { json: { company: 'ACME BUILDERS', state: 'ND', license_number: '',
            known_status: '' } },
];

// state -> { actor, field }
// `field` matters: these actors do NOT share one input name.
const ACTORS = {
  AL: { actor: 'scrapebench~alabama-contractor-license-lookup',        field: 'query' },
  AR: { actor: 'scrapebench~arkansas-contractor-license-lookup',       field: 'query' },
  CA: { actor: 'scrapebench~california-contractor-license-lookup',     field: 'query' },
  CT: { actor: 'scrapebench~multistate-contractor-license-lookup',     field: 'query', extra: { states: ['CT'] } },
  FL: { actor: 'scrapebench~florida-contractor-license-lookup',        field: 'query' },
  MA: { actor: 'scrapebench~massachusetts-construction-license-lookup', field: 'query' },
  MI: { actor: 'scrapebench~michigan-contractor-license-lookup',       field: 'query' },
  MN: { actor: 'scrapebench~minnesota-contractor-license-lookup',      field: 'query' },
  NC: { actor: 'scrapebench~north-carolina-contractor-license-lookup', field: 'query' },
  NM: { actor: 'scrapebench~new-mexico-contractor-license-lookup',     field: 'businessName' },
  NV: { actor: 'scrapebench~nevada-contractor-license-lookup',         field: 'query' },
  OR: { actor: 'scrapebench~oregon-contractor-license-lookup',         field: 'query' },
  SC: { actor: 'scrapebench~south-carolina-contractor-license-lookup', field: 'lastName' },
  TN: { actor: 'scrapebench~tennessee-contractor-license-lookup',      field: 'query' },
  TX: { actor: 'scrapebench~texas-contractor-license-lookup',          field: 'query' },
  VA: { actor: 'scrapebench~virginia-contractor-license-lookup',       field: 'nameFilter' },
  WA: { actor: 'scrapebench~washington-contractor-license-lookup',     field: 'query' },
};

return $input.all().map((item) => {
  const lead = item.json;
  const state = String(lead.state || '').trim().toUpperCase();
  const cfg = ACTORS[state];

  if (!cfg) {
    // Not covered. Pass it through labelled - never drop it, never call it unlicensed.
    return { json: { ...lead, covered: false, verification_status: 'unverifiable - state not covered' } };
  }

  // Prefer an exact licence number when the row has one; otherwise search the name.
  // `includeDetails` matters here: expiry lives on the detail tier, not the summary row.
  const term = String(lead.license_number || '').trim() || String(lead.company || '').trim();
  const input = { [cfg.field]: term, maxResults: 5, includeDetails: true, ...(cfg.extra || {}) };

  return { json: { ...lead, covered: true, actorId: cfg.actor, actorInput: JSON.stringify(input) } };
});

// Pair each returned licence back to the roster row that asked for it, then decide whether
// anything changed that a human needs to see.
//
// Tiers, worst first. `check-failed` is the one that matters most: a monitor that goes quiet
// when the lookup breaks is worse than no monitor, because silence reads as "all fine".
const WARN_DAYS = 30;

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// State portals publish dates in whatever format they like. Accept the common ones and, when a
// date can't be read, say so rather than silently treating it as "not expiring".
function parseDate(v) {
  const s = String(v || '').trim();
  if (!s) return null;
  let m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);      // 10/17/2026
  if (m) return new Date(Date.UTC(+m[3], +m[1] - 1, +m[2]));
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);                          // 2026-10-17
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

const today = new Date();
const roster = $('Route by state').all().map((i) => i.json).filter((r) => r.covered);

// Group the returned rows by the roster row that asked for them, using n8n's paired-item link
// rather than re-matching on name. Matching on name alone silently loses states whose summary
// row carries no name at all - Nevada returns a licence with `business_name` and `person_name`
// both null, which read as "no match at the portal" while a revoked licence sat in the result.
const byRow = {};
for (const item of $input.all()) {
  const p = item.pairedItem;
  const idx = typeof p === 'number' ? p : Array.isArray(p) ? p[0]?.item : p?.item;
  (byRow[idx ?? 0] = byRow[idx ?? 0] || []).push(item.json);
}

const out = [];
for (let i = 0; i < roster.length; i++) {
  const row = roster[i];
  const returned = byRow[i] || [];
  // The Apify node continues on error, so a failed lookup arrives as a row carrying `error`
  // instead of licence data. "We could not check" is not "the portal has no record".
  const failureNote = returned.find((r) => r.error) ? String(returned.find((r) => r.error).error) : null;
  const rows = returned.filter((r) => !r.error && (r.license_number || r.status));

  const wanted = String(row.license_number || '').trim();
  let hits = [];
  if (wanted) {
    hits = rows.filter((r) => String(r.license_number || '').trim().toUpperCase() === wanted.toUpperCase());
  } else {
    const a = norm(row.company);
    hits = rows.filter((r) => {
      const b = norm(r.business_name || r.company_name || r.person_name);
      return a && b && (a === b || b.includes(a) || a.includes(b));
    });
    // Nothing name-matched, but the portal did answer this row. One answer is that row's answer;
    // several is genuinely ambiguous and goes to a human rather than being guessed at.
    if (!hits.length && rows.length === 1) hits = rows;
  }

  const base = { company: row.company, state: row.state, license_number: row.license_number || null };

  if (!hits.length && rows.length > 1) {
    out.push({ json: { ...base, alert_tier: 'ambiguous',
                       headline: `${rows.length} licences matched that name - pick one by hand`,
                       detail: 'Add the licence number to this roster row to make the check exact.' } });
    continue;
  }

  if (!hits.length) {
    if (failureNote) {
      // The lookup itself broke - bad token, actor failure, timeout. We know nothing about this
      // licence. Never let this pass as fine, and never dress it up as a portal result.
      out.push({ json: { ...base, alert_tier: 'check-failed',
                         headline: 'Lookup failed - this licence was NOT checked',
                         detail: failureNote } });
    } else {
      // The lookup ran fine and the portal had no match. Different thing, different message.
      out.push({ json: { ...base, alert_tier: 'not-found',
                         headline: 'No match at the state portal',
                         detail: 'Not proof of anything: contractors are routinely licensed under a legal name that differs from the name on your roster.' } });
    }
    continue;
  }

  const hit = hits[0];
  const status = hit.status ?? null;
  const expiry = hit.expiration_date ?? null;
  const exp = parseDate(expiry);
  const days = exp ? Math.ceil((exp - today) / 86400000) : null;
  // Order matters: the negative list is checked FIRST. "This license is inactive" contains the
  // substring "active", so a naive /active|current/ test reports a dead licence as healthy.
  const st = String(status || '').toLowerCase();
  const bad = /(inactive|expired|suspend|revoked|cancel|void|delinquent|lapsed|not renewed)/.test(st);
  const active = !bad && /(active|current|valid|good standing)/.test(st);

  const known = String(row.known_status || '').trim();
  const statusChanged = known && norm(known) !== norm(status);

  let tier, headline;
  if (exp && days < 0) {
    tier = 'expired';
    headline = `Licence expired ${Math.abs(days)} day(s) ago (${expiry})`;
  } else if (statusChanged || !active) {
    tier = 'status-change';
    headline = known ? `Status changed: ${known} -> ${status}` : `Status is ${status || 'unknown'}`;
  } else if (exp && days <= WARN_DAYS) {
    tier = 'expiring';
    headline = `Expires in ${days} day(s) (${expiry})`;
  } else if (!exp) {
    // Not every state publishes an expiry. Say that plainly instead of implying "no expiry = fine".
    tier = 'no-expiry-published';
    headline = 'This state does not publish an expiry date for this licence';
  } else {
    tier = 'ok';
    headline = `Active, expires ${expiry} (${days} days)`;
  }

  out.push({ json: { ...base, alert_tier: tier, headline,
                     license_status: status, license_expiry: expiry, days_to_expiry: days,
                     matched_name: hit.business_name ?? hit.person_name ?? null,
                     source_url: hit.source_url ?? null } });
}
return out;

// One message, grouped worst-first. A monitor that sends one alert per row trains people to
// mute it, and a muted monitor is the same as no monitor.
const ORDER = ['expired', 'status-change', 'expiring', 'check-failed', 'ambiguous', 'not-found', 'no-expiry-published'];
const LABEL = {
  'expired': ':red_circle: EXPIRED',
  'status-change': ':large_orange_circle: STATUS CHANGED',
  'expiring': ':warning: EXPIRING WITHIN 30 DAYS',
  'check-failed': ':rotating_light: COULD NOT CHECK (lookup failed)',
  'ambiguous': ':grey_question: SEVERAL LICENCES MATCH',
  'not-found': ':grey_question: NO MATCH AT THE PORTAL',
  'no-expiry-published': ':information_source: NO EXPIRY PUBLISHED',
};

const rows = $input.all().map((i) => i.json);
const lines = [`*Contractor licence check* - ${rows.length} item(s) need attention`];

for (const tier of ORDER) {
  const group = rows.filter((r) => r.alert_tier === tier);
  if (!group.length) continue;
  lines.push('', `${LABEL[tier]}  (${group.length})`);
  for (const r of group) {
    const where = r.source_url ? ` <${r.source_url}|portal>` : '';
    lines.push(`- *${r.company}* (${r.state}) - ${r.headline}${where}`);
  }
}

return [{ json: { text: lines.join('\n'), alert_count: rows.length } }];
